#pragma once
#ifndef _USB_LOG_H_
#define _USB_LOG_H_

// Text output over USB serial (CDC). Needs the USB_DEVICE CDC middleware generated by
// CubeMX; without it every call is a no-op and usb_log_available() returns 0.
// Output is dropped (not queued) while no host has the port configured.

#include <stdint.h>

int usb_log_available(void); // CDC middleware compiled in
int usb_log_connected(void); // host has enumerated the device

void usb_log_write(const char *s);
void usb_log_printf(const char *fmt, ...) __attribute__((format(printf, 1, 2)));

#endif
